FUNCTION_BLOCK FB
VAR_INPUT
    openBtn : BOOL;
    closeBtn : BOOL;
    openLimit : BOOL;
    closeLimit : BOOL;
    obstacle : BOOL;
END_VAR
VAR_OUTPUT
    motorUp : BOOL;
    motorDown : BOOL;
    errorFlag : BOOL;
END_VAR
VAR
    state : INT := 0;
    openBtnPrev : BOOL;
    closeBtnPrev : BOOL;
    openBtnRise : BOOL;
    closeBtnRise : BOOL;
END_VAR

openBtnRise := openBtn AND NOT openBtnPrev;
closeBtnRise := closeBtn AND NOT closeBtnPrev;

CASE state OF
    0:
        IF openBtnRise AND NOT closeBtnRise AND NOT openLimit THEN
            state := 1;
        ELSIF closeBtnRise AND NOT openBtnRise AND NOT closeLimit THEN
            state := 2;
        END_IF
    1:
        IF obstacle THEN
            state := 3;
        ELSIF openLimit THEN
            state := 0;
        END_IF
    2:
        IF obstacle THEN
            state := 1;
        ELSIF closeLimit THEN
            state := 0;
        END_IF
    3:
        IF openBtn AND closeBtn THEN
            state := 0;
        END_IF
END_CASE

motorUp := state = 1 AND NOT openLimit;
motorDown := state = 2 AND NOT closeLimit AND NOT obstacle;
errorFlag := state = 3;

openBtnPrev := openBtn;
closeBtnPrev := closeBtn;

END_FUNCTION_BLOCK
